/* Rascunho — Raciocínio lógico / Argumentos válidos e falácias.
   Validade conferida por tabela-verdade: um argumento é válido quando não há
   linha com todas as premissas verdadeiras e a conclusão falsa. As questões
   de falácia informal não têm conferência em código.

   Alternativas que não são proposições sobre os átomos da questão (“nada se
   pode concluir”, afirmações universais sobre outras pessoas) entram como
   `() => false`: o que se confere é que a correta decorre e que as
   alternativas proposicionais não decorrem. Cuidado que a conferência já
   pegou: quando as premissas fixam o valor de todos os átomos, recíprocas e
   inversas passam a decorrer por vacuidade — não servem de distrator. */

export const materia = "raciocinio-logico";
export const tema = "Argumentos válidos e falácias";
export const arquivo = "raciocinio-logico__argumentos-validos-e-falacias";

const tabela = (n) => Array.from({ length: 2 ** n }, (_, m) => Array.from({ length: n }, (_, k) => Boolean((m >> k) & 1)));
const imp = (a, b) => !a || b;
const valido = (premissas, conclusao, n) => tabela(n).every((a) => !premissas(...a) || conclusao(...a));
const unicoV = (arr) => { const ok = arr.map((b, i) => (b ? i : -1)).filter((i) => i >= 0); return ok.length === 1 ? ok[0] : -1; };
/* Das conclusões candidatas, só uma pode decorrer das premissas. */
const decorre = (premissas, ops, n) => unicoV(ops.map((c) => valido(premissas, c, n)));

